#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "sdb.h"

int main(void) {
    Sdb *parent, *child;
    int i;

    parent = sdb_new0();
    child = sdb_new0();

    printf("Initial refs: parent->refs=%d, child->refs=%d\n", parent->refs, child->refs);

    /* Set the same child as two different namespaces */
    sdb_ns_set(parent, "ns1", child);
    printf("After ns1: child->refs=%d\n", child->refs);
    sdb_ns_set(parent, "ns2", child);
    printf("After ns2: child->refs=%d\n", child->refs);

    printf("Calling sdb_free(parent)...\n");
    fflush(stdout);

    /* This should trigger the use-after-free */
    sdb_free(parent);

    printf("Done (should not reach here if crash occurred)\n");
    return 0;
}
EOF

